// Krok 2: podpis HMAC — odrzuć żądanie, które nie przyszło z TIMPORYE (docs/ZDARZENIA-N8N.md)
const crypto = require('crypto');
const secret = $env.TIMPORYE_WEBHOOK_SECRET;            // ten sam co AUTOMATION_WEBHOOK_SECRET w aplikacji
const body = Buffer.from($input.first().binary.data.data, 'base64');
const expected = Buffer.from('sha256=' + crypto.createHmac('sha256', secret).update(body).digest('hex'));
const got = Buffer.from($input.first().json.headers['x-timporye-signature'] || '');
if (got.length !== expected.length || !crypto.timingSafeEqual(expected, got)) {
  throw new Error('Zły podpis — żądanie nie pochodzi z TIMPORYE');
}
return [{ json: JSON.parse(body.toString('utf8')) }];

// Krok 5: karta do kanału Teams (Workflows „Post to a channel when a webhook request is received”)
const e = $('Sprawdź podpis').first().json;
const c = $input.first().json;
const panel = $env.TIMPORYE_PANEL_URL;                   // np. https://container.queue.twapp.pl
return [{ json: {
  type: 'message',
  attachments: [{
    contentType: 'application/vnd.microsoft.card.adaptive',
    content: {
      $schema: 'http://adaptivecards.io/schemas/adaptive-card.json', type: 'AdaptiveCard', version: '1.4',
      body: [
        { type: 'TextBlock', text: e.title, weight: 'Bolder', wrap: true },
        { type: 'FactSet', facts: [
          { title: 'Statek', value: c.vessel || '—' },
          { title: 'ETA', value: c.eta || '—' },
          { title: 'Magazyn', value: c.warehouse_name || '—' },
        ] },
      ],
      actions: [{ type: 'Action.OpenUrl', title: 'Otwórz w aplikacji', url: `${panel}/kontenery/${e.container_id}` }],
    },
  }],
} }];
